from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


def replace_once(path: Path, old: str, new: str, label: str):
    text = path.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected 1 match, found {count}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")


# 1) Refactor the loudness estimator so Android can feed decoded PCM directly without WAV/resampling.
estimator = ROOT / "app/src/main/java/vn/nghetruyen/app/audio/PcmLoudnessEstimator.kt"
replace_once(
    estimator,
    '''    private data class Segment(val energy: Double, val frames: Int)\n\n    fun analyze(wavFile: File): Analysis {\n''',
    '''    private data class Segment(val energy: Double, val frames: Int)\n\n    internal class StreamingAnalyzer(\n        private val sampleRate: Int,\n        private val channels: Int,\n    ) {\n        private val shelf: Coefficients\n        private val highPass: Coefficients\n        private val states: Array<ChannelState>\n        private val weights: DoubleArray\n        private val stepFrames: Int\n        private val frameBytes: Int\n        private val segments = mutableListOf<Segment>()\n        private var segmentEnergy = 0.0\n        private var segmentFrames = 0\n        private var peak = 0.0\n        private var finished = false\n\n        init {\n            require(sampleRate in 8_000..384_000) { "Sample rate PCM không hợp lệ." }\n            require(channels in 1..8) { "Số kênh PCM không được hỗ trợ." }\n            shelf = shelfCoefficients(sampleRate.toDouble())\n            highPass = highPassCoefficients(sampleRate.toDouble())\n            states = Array(channels) { ChannelState() }\n            weights = channelWeights(channels)\n            stepFrames = (sampleRate / 10.0 + 0.5).toInt().coerceAtLeast(1)\n            frameBytes = channels * 2\n        }\n\n        fun acceptPcm16(bytes: ByteArray, offset: Int = 0, length: Int = bytes.size - offset) {\n            check(!finished) { "Bộ đo loudness đã kết thúc." }\n            require(offset >= 0 && length >= 0 && offset + length <= bytes.size)\n            require(length % frameBytes == 0) { "PCM16 không thẳng hàng theo frame." }\n            var cursor = offset\n            val end = offset + length\n            while (cursor < end) {\n                var weighted = 0.0\n                for (channel in 0 until channels) {\n                    val lo = bytes[cursor].toInt() and 0xff\n                    val hi = bytes[cursor + 1].toInt()\n                    val sample = ((lo or (hi shl 8)).toShort().toDouble() / 32768.0)\n                    peak = maxOf(peak, abs(sample))\n                    val state = states[channel]\n                    var filtered = filterSample(state.shelf, shelf, sample)\n                    filtered = filterSample(state.highPass, highPass, filtered)\n                    weighted += filtered * filtered * weights[channel]\n                    cursor += 2\n                }\n                segmentEnergy += weighted\n                segmentFrames += 1\n                if (segmentFrames >= stepFrames) {\n                    segments += Segment(segmentEnergy, segmentFrames)\n                    segmentEnergy = 0.0\n                    segmentFrames = 0\n                }\n            }\n        }\n\n        fun finish(): Analysis {\n            check(!finished) { "Bộ đo loudness đã kết thúc." }\n            finished = true\n            if (segmentFrames > 0) {\n                segments += Segment(segmentEnergy, segmentFrames)\n                segmentEnergy = 0.0\n                segmentFrames = 0\n            }\n            val loudness = integratedLoudness(segments)\n                ?: throw IOException("Bản nhạc không có đủ tín hiệu để đo độ lớn.")\n            val peakDbfs = if (peak > 0.0) 20.0 * log10(peak) else -120.0\n            return Analysis(\n                loudnessLufs = loudness.toFloat(),\n                peakDbfs = peakDbfs.toFloat(),\n            )\n        }\n    }\n\n    fun analyze(wavFile: File): Analysis {\n''',
    "streaming loudness analyzer",
)

old_body = '''        val shelf = shelfCoefficients(sampleRate.toDouble())\n        val highPass = highPassCoefficients(sampleRate.toDouble())\n        val states = Array(channels) { ChannelState() }\n        val weights = channelWeights(channels)\n        val stepFrames = (sampleRate / 10.0 + 0.5).toInt().coerceAtLeast(1)\n        val frameBytes = channels * 2\n        val bufferSize = (64 * 1024 / frameBytes) * frameBytes\n        val buffer = ByteArray(bufferSize.coerceAtLeast(frameBytes))\n        val segments = mutableListOf<Segment>()\n        var segmentEnergy = 0.0\n        var segmentFrames = 0\n        var peak = 0.0\n\n        BufferedInputStream(FileInputStream(wavFile)).use { input ->\n            skipFully(input, wave.dataOffset)\n            var remaining = wave.dataLength\n            while (remaining > 0) {\n                val wanted = min(buffer.size.toLong(), remaining).toInt()\n                var readTotal = 0\n                while (readTotal < wanted) {\n                    val count = input.read(buffer, readTotal, wanted - readTotal)\n                    if (count < 0) throw EOFException("PCM bị cắt ngắn.")\n                    readTotal += count\n                }\n                val completeBytes = readTotal - (readTotal % frameBytes)\n                var offset = 0\n                while (offset < completeBytes) {\n                    var weighted = 0.0\n                    for (channel in 0 until channels) {\n                        val lo = buffer[offset].toInt() and 0xff\n                        val hi = buffer[offset + 1].toInt()\n                        val sample = ((lo or (hi shl 8)).toShort().toDouble() / 32768.0)\n                        peak = maxOf(peak, abs(sample))\n                        val state = states[channel]\n                        var filtered = filterSample(state.shelf, shelf, sample)\n                        filtered = filterSample(state.highPass, highPass, filtered)\n                        weighted += filtered * filtered * weights[channel]\n                        offset += 2\n                    }\n                    segmentEnergy += weighted\n                    segmentFrames += 1\n                    if (segmentFrames >= stepFrames) {\n                        segments += Segment(segmentEnergy, segmentFrames)\n                        segmentEnergy = 0.0\n                        segmentFrames = 0\n                    }\n                }\n                remaining -= readTotal\n            }\n        }\n        if (segmentFrames > 0) segments += Segment(segmentEnergy, segmentFrames)\n\n        val loudness = integratedLoudness(segments)\n            ?: throw IOException("Bản nhạc không có đủ tín hiệu để đo độ lớn.")\n        val peakDbfs = if (peak > 0.0) 20.0 * log10(peak) else -120.0\n        return Analysis(\n            loudnessLufs = loudness.toFloat(),\n            peakDbfs = peakDbfs.toFloat(),\n        )\n'''
new_body = '''        val frameBytes = channels * 2\n        val bufferSize = (64 * 1024 / frameBytes) * frameBytes\n        val buffer = ByteArray(bufferSize.coerceAtLeast(frameBytes))\n        val analyzer = StreamingAnalyzer(sampleRate, channels)\n\n        BufferedInputStream(FileInputStream(wavFile)).use { input ->\n            skipFully(input, wave.dataOffset)\n            var remaining = wave.dataLength\n            while (remaining > 0) {\n                val wanted = min(buffer.size.toLong(), remaining).toInt()\n                var readTotal = 0\n                while (readTotal < wanted) {\n                    val count = input.read(buffer, readTotal, wanted - readTotal)\n                    if (count < 0) throw EOFException("PCM bị cắt ngắn.")\n                    readTotal += count\n                }\n                val completeBytes = readTotal - (readTotal % frameBytes)\n                if (completeBytes > 0) analyzer.acceptPcm16(buffer, 0, completeBytes)\n                remaining -= readTotal\n            }\n        }\n        return analyzer.finish()\n'''
replace_once(estimator, old_body, new_body, "reuse streaming analyzer for wav")

# 2) Direct Android MediaCodec loudness path: no temporary WAV, no resample, no channel conversion.
stream_file = ROOT / "app/src/main/java/vn/nghetruyen/app/audio/AndroidAudioLoudnessAnalyzer.kt"
stream_file.write_text('''package vn.nghetruyen.app.audio\n\nimport android.content.Context\nimport android.media.AudioFormat\nimport android.media.MediaCodec\nimport android.media.MediaExtractor\nimport android.media.MediaFormat\nimport android.net.Uri\nimport java.io.IOException\nimport java.nio.ByteBuffer\nimport java.nio.ByteOrder\n\n/**\n * Fast Mode-3 loudness measurement. The source MP3/OGG is never rewritten. MediaCodec only\n * exposes decoded PCM buffers in memory and they are fed directly to the LUFS estimator at the\n * source sample rate/channel count. This deliberately avoids temporary WAV I/O and resampling.\n */\nobject AndroidAudioLoudnessAnalyzer {\n    private const val TIMEOUT_US = 10_000L\n\n    fun analyze(\n        context: Context,\n        uri: Uri,\n        maxDecodeDurationUs: Long,\n    ): PcmLoudnessEstimator.Analysis {\n        require(maxDecodeDurationUs > 0L)\n        val extractor = MediaExtractor()\n        var codec: MediaCodec? = null\n        try {\n            extractor.setDataSource(context, uri, null)\n            val trackIndex = (0 until extractor.trackCount).firstOrNull { index ->\n                extractor.getTrackFormat(index).getString(MediaFormat.KEY_MIME)?.startsWith("audio/") == true\n            } ?: throw IOException("Tệp âm thanh không có track âm thanh.")\n            extractor.selectTrack(trackIndex)\n            val inputFormat = extractor.getTrackFormat(trackIndex)\n            val mime = inputFormat.getString(MediaFormat.KEY_MIME)\n                ?: throw IOException("Tệp âm thanh thiếu MIME codec.")\n            codec = MediaCodec.createDecoderByType(mime)\n            codec.configure(inputFormat, null, null, 0)\n            codec.start()\n\n            var inputDone = false\n            var outputDone = false\n            var analyzer: PcmLoudnessEstimator.StreamingAnalyzer? = null\n            var analyzerRate = -1\n            var analyzerChannels = -1\n            var pcmEncoding = AudioFormat.ENCODING_PCM_16BIT\n            val info = MediaCodec.BufferInfo()\n\n            fun ensureAnalyzer(format: MediaFormat): PcmLoudnessEstimator.StreamingAnalyzer {\n                val rate = format.getInteger(MediaFormat.KEY_SAMPLE_RATE)\n                val channels = format.getInteger(MediaFormat.KEY_CHANNEL_COUNT)\n                val encoding = if (format.containsKey(MediaFormat.KEY_PCM_ENCODING)) {\n                    format.getInteger(MediaFormat.KEY_PCM_ENCODING)\n                } else AudioFormat.ENCODING_PCM_16BIT\n                if (encoding !in setOf(AudioFormat.ENCODING_PCM_16BIT, AudioFormat.ENCODING_PCM_FLOAT)) {\n                    throw IOException("PCM $encoding của track chưa được hỗ trợ.")\n                }\n                pcmEncoding = encoding\n                val current = analyzer\n                if (current == null) {\n                    analyzerRate = rate\n                    analyzerChannels = channels\n                    return PcmLoudnessEstimator.StreamingAnalyzer(rate, channels).also { analyzer = it }\n                }\n                if (rate != analyzerRate || channels != analyzerChannels) {\n                    throw IOException("Định dạng PCM thay đổi giữa lúc phân tích.")\n                }\n                return current\n            }\n\n            while (!outputDone) {\n                if (!inputDone) {\n                    val inputIndex = codec.dequeueInputBuffer(TIMEOUT_US)\n                    if (inputIndex >= 0) {\n                        val inputBuffer = codec.getInputBuffer(inputIndex)\n                            ?: throw IOException("Audio decoder không cung cấp input buffer.")\n                        inputBuffer.clear()\n                        val sampleTimeUs = extractor.sampleTime.coerceAtLeast(0L)\n                        val durationReached = sampleTimeUs >= maxDecodeDurationUs\n                        val size = if (durationReached) -1 else extractor.readSampleData(inputBuffer, 0)\n                        if (size < 0) {\n                            codec.queueInputBuffer(\n                                inputIndex,\n                                0,\n                                0,\n                                sampleTimeUs,\n                                MediaCodec.BUFFER_FLAG_END_OF_STREAM,\n                            )\n                            inputDone = true\n                        } else {\n                            codec.queueInputBuffer(inputIndex, 0, size, sampleTimeUs, 0)\n                            extractor.advance()\n                        }\n                    }\n                }\n\n                when (val outputIndex = codec.dequeueOutputBuffer(info, TIMEOUT_US)) {\n                    MediaCodec.INFO_TRY_AGAIN_LATER -> Unit\n                    MediaCodec.INFO_OUTPUT_FORMAT_CHANGED -> ensureAnalyzer(codec.outputFormat)\n                    else -> if (outputIndex >= 0) {\n                        try {\n                            if (info.size > 0) {\n                                val output = codec.getOutputBuffer(outputIndex)\n                                    ?: throw IOException("Audio decoder không cung cấp output buffer.")\n                                val activeAnalyzer = ensureAnalyzer(codec.outputFormat)\n                                output.position(info.offset)\n                                output.limit(info.offset + info.size)\n                                val bytes = ByteArray(info.size)\n                                output.get(bytes)\n                                val pcm16 = when (pcmEncoding) {\n                                    AudioFormat.ENCODING_PCM_FLOAT -> floatPcmTo16(bytes)\n                                    else -> bytes\n                                }\n                                activeAnalyzer.acceptPcm16(pcm16)\n                            }\n                            outputDone = (info.flags and MediaCodec.BUFFER_FLAG_END_OF_STREAM) != 0\n                        } finally {\n                            codec.releaseOutputBuffer(outputIndex, false)\n                        }\n                    }\n                }\n            }\n            return analyzer?.finish()\n                ?: throw IOException("Không giải mã được PCM từ track âm thanh.")\n        } finally {\n            runCatching { codec?.stop() }\n            runCatching { codec?.release() }\n            runCatching { extractor.release() }\n        }\n    }\n\n    private fun floatPcmTo16(bytes: ByteArray): ByteArray {\n        if (bytes.size % 4 != 0) throw IOException("PCM float không thẳng hàng theo mẫu.")\n        val input = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN)\n        val output = ByteBuffer.allocate(bytes.size / 2).order(ByteOrder.LITTLE_ENDIAN)\n        while (input.remaining() >= 4) {\n            val sample = input.float.coerceIn(-1f, 1f)\n            output.putShort((sample * Short.MAX_VALUE).toInt().toShort())\n        }\n        return output.array()\n    }\n}\n''', encoding="utf-8")

