# 6) Regression tests for streaming chunk analysis and vague-wind SFX repair.
test_audio = ROOT / "app/src/test/java/vn/nghetruyen/app/audio/Mode3StreamingLoudnessTest.kt"
test_audio.write_text('''package vn.nghetruyen.app.audio\n\nimport kotlin.math.PI\nimport kotlin.math.sin\nimport org.junit.Assert.assertTrue\nimport org.junit.Test\n\nclass Mode3StreamingLoudnessTest {\n    @Test\n    fun streamingAnalyzerMeasuresChunkedNativePcmWithoutWaveConversion() {\n        val sampleRate = 48_000\n        val channels = 2\n        val frames = sampleRate * 2\n        val pcm = ByteArray(frames * channels * 2)\n        var offset = 0\n        for (frame in 0 until frames) {\n            val sample = (sin(2.0 * PI * 440.0 * frame / sampleRate) * 0.25 * Short.MAX_VALUE).toInt().toShort()\n            repeat(channels) {\n                pcm[offset++] = (sample.toInt() and 0xff).toByte()\n                pcm[offset++] = ((sample.toInt() ushr 8) and 0xff).toByte()\n            }\n        }\n        val analyzer = PcmLoudnessEstimator.StreamingAnalyzer(sampleRate, channels)\n        val frameBytes = channels * 2\n        var cursor = 0\n        while (cursor < pcm.size) {\n            val bytes = minOf(12_000, pcm.size - cursor)\n            val aligned = bytes - (bytes % frameBytes)\n            analyzer.acceptPcm16(pcm, cursor, aligned)\n            cursor += aligned\n        }\n        val result = analyzer.finish()\n        assertTrue(result.loudnessLufs.isFinite())\n        assertTrue(result.peakDbfs in -13f..-11f)\n    }\n}\n''', encoding="utf-8")

test_req = ROOT / "app/src/test/java/vn/nghetruyen/app/freesound/FreesoundMode3RegressionTest.kt"
text = test_req.read_text(encoding="utf-8")
method = '''\n    @Test\n    fun vagueContinuousWindIsNotKeptAsAnSfxQuery() {\n        assertEquals(\n            "wind gust",\n            FreesoundAutoRequirementCodec.canonicalSearchQuery("heavy wind", AudioAssetKind.SFX),\n        )\n        assertEquals(\n            "heavy wind",\n            FreesoundAutoRequirementCodec.canonicalSearchQuery("heavy wind", AudioAssetKind.AMBIENCE),\n        )\n        assertEquals(\n            "wind whoosh",\n            FreesoundAutoRequirementCodec.canonicalSearchQuery("wind whoosh", AudioAssetKind.SFX),\n        )\n    }\n'''
if "vagueContinuousWindIsNotKeptAsAnSfxQuery" not in text:
    pos = text.rfind("}\n")
    if pos < 0:
        raise RuntimeError("FreesoundMode3RegressionTest closing brace not found")
    text = text[:pos] + method + text[pos:]
test_req.write_text(text, encoding="utf-8")

print("Mode 3 V12 streaming normalization patch applied successfully.")
